 static bool command(Document& d,const JsonObject& row){const auto op=row.GetNamedString(L"operation");const auto p=d.selectionPivotHistory_.pivot;if(op==L"crop")return d.cropCanvas(p);if(op==L"trim-all"||op==L"trim-current")return d.trimCanvas(op==L"trim-all",p);std::optional<int> x,y;if(row.GetNamedValue(L"dx").ValueType()==JsonValueType::Number)x=int(row.GetNamedNumber(L"dx"));if(row.GetNamedValue(L"dy").ValueType()==JsonValueType::Number)y=int(row.GetNamedNumber(L"dy"));return d.resizeCanvas(int(row.GetNamedNumber(L"tw")),int(row.GetNamedNumber(L"th")),CanvasAnchor(int(row.GetNamedNumber(L"anchor"))),x,y,row.GetNamedBoolean(L"trim"),p);}
